  if (index != null && contentBlock is Map<String, dynamic>) {
    final block = _createStreamingBlock(contentBlock);
    if (block != null) {
      blocks.add(block);
      blocksByEventIndex[index] = block;
      final startIndex = blocks.indexOf(block);
