              contentIndex: startIndex,
              partial: state.snapshot(),
            ),
          );
        case ThinkingStreamingBlock():
          eventStream.push(
            ThinkingStartEvent(
              contentIndex: startIndex,
              partial: state.snapshot(),
            ),
          );
        case ToolCallStreamingBlock():
