/// Server-Sent Events (SSE) line decoder.
///
/// Ported from the hand-rolled decoder in pi-mono
/// `packages/ai/src/api/anthropic-messages.ts` (`iterateSseMessages`,
/// `decodeSseLine`, `flushSseEvent`, `consumeLine`, `nextLineBreakIndex`).
/// Kept mechanically close to the original so future pi fixes port trivially.
///
/// Unlike pi — which decodes bytes with `TextDecoder` inside the iterator —
/// this decoder consumes a `Stream<String>` of arbitrarily-split text chunks.
/// Byte streams are decoded upstream, e.g.:
///
/// ```dart
/// final events = byteStream
///     .transform(utf8.decoder)
///     .transform(const SseDecoder());
/// ```
library;

import 'dart:async';

/// A parsed Server-Sent Event.
///
/// Ported from pi's `ServerSentEvent`.
final class ServerSentEvent {
  ServerSentEvent({required this.event, required this.data, required this.raw});

  /// The `event:` field value, or `null` when the event had none.
  final String? event;

  /// The `data:` field values joined with `\n` (multi-line data per the SSE
  /// spec).
  final String data;

  /// The raw lines that made up this event, for diagnostics.
  final List<String> raw;
}

final class _SseDecoderState {
  String? event;
  final data = <String>[];
  final raw = <String>[];
}

ServerSentEvent? _flushSseEvent(_SseDecoderState state) {
  if (state.event == null && state.data.isEmpty) {
    return null;
  }

  final event = ServerSentEvent(
    event: state.event,
    data: state.data.join('\n'),
    raw: List.of(state.raw),
  );
  state.event = null;
  state.data.clear();
  state.raw.clear();
  return event;
}

ServerSentEvent? _decodeSseLine(String line, _SseDecoderState state) {
  if (line.isEmpty) {
    return _flushSseEvent(state);
  }

  state.raw.add(line);
  if (line.startsWith(':')) {
    // Comment line (also used for heartbeats).
    return null;
  }

  final delimiterIndex = line.indexOf(':');
  final fieldName = delimiterIndex == -1
      ? line
      : line.substring(0, delimiterIndex);
  var value = delimiterIndex == -1 ? '' : line.substring(delimiterIndex + 1);
  if (value.startsWith(' ')) {
    value = value.substring(1);
  }

  if (fieldName == 'event') {
    state.event = value;
  } else if (fieldName == 'data') {
    state.data.add(value);
  }
  // Other fields (id, retry, field-less lines, ...) are ignored, per the SSE
  // spec and pi's behavior.

  return null;
}

int _nextLineBreakIndex(String text) {
  final carriageReturnIndex = text.indexOf('\r');
  final newlineIndex = text.indexOf('\n');
  if (carriageReturnIndex == -1) {
    return newlineIndex;
  }
  if (newlineIndex == -1) {
    return carriageReturnIndex;
  }
  return carriageReturnIndex < newlineIndex
      ? carriageReturnIndex
      : newlineIndex;
}

({String line, String rest})? _consumeLine(String text) {
  final lineBreakIndex = _nextLineBreakIndex(text);
  if (lineBreakIndex == -1) {
    return null;
  }

  var nextIndex = lineBreakIndex + 1;
  if (text[lineBreakIndex] == '\r' &&
      nextIndex < text.length &&
      text[nextIndex] == '\n') {
    nextIndex += 1;
  }

  return (
    line: text.substring(0, lineBreakIndex),
    rest: text.substring(nextIndex),
  );
}

/// Decodes a stream of text chunks into [ServerSentEvent]s.
///
/// Handles LF, CRLF, and lone-CR line endings, events split across chunks,
/// comment (`:`) lines, and multi-line `data:` fields. A trailing event not
/// terminated by a blank line is flushed when the input stream closes —
/// matching pi's behavior.
class SseDecoder extends StreamTransformerBase<String, ServerSentEvent> {
  const SseDecoder();

  @override
  Stream<ServerSentEvent> bind(Stream<String> stream) async* {
    final state = _SseDecoderState();
    var buffer = '';
    // The SSE spec requires stripping a single UTF-8 BOM at the very start
    // of the stream. Upstream byte decoding (utf8.decoder) always delivers
    // the BOM as one leading U+FEFF character, possibly after empty chunks.
    var atStreamStart = true;

    await for (final chunk in stream) {
      buffer += chunk;
      if (atStreamStart && buffer.isNotEmpty) {
        atStreamStart = false;
        if (buffer.startsWith('\uFEFF')) buffer = buffer.substring(1);
      }
      final (rest, events) = _drainSseLines(buffer, state);
      buffer = rest;
      for (final event in events) {
        yield event;
      }
    }

    // Flush whatever the final chunk left behind.
    final (rest, events) = _drainSseLines(buffer, state);
    buffer = rest;
    for (final event in events) {
      yield event;
    }

    if (buffer.isNotEmpty) {
      final event = _decodeSseLine(buffer, state);
      if (event != null) {
        yield event;
      }
    }

    final trailingEvent = _flushSseEvent(state);
    if (trailingEvent != null) {
      yield trailingEvent;
    }
  }

  /// Decodes every complete line in [buffer], returning the unconsumed rest
  /// and the parsed events.
  (String, List<ServerSentEvent>) _drainSseLines(
    String buffer,
    _SseDecoderState state,
  ) {
    final events = <ServerSentEvent>[];
    var consumed = _consumeLine(buffer);
    while (consumed != null) {
      buffer = consumed.rest;
      final event = _decodeSseLine(consumed.line, state);
      if (event != null) {
        events.add(event);
      }
      consumed = _consumeLine(buffer);
    }
    return (buffer, events);
  }
}

Now I understand the SSE decoder. `sse.event` is the `event:` field value or `null` when absent. `sse.data` is the joined data lines (String, never null).

Now let me analyze the new `_sseEventName`:

```dart
String? _sseEventName(ServerSentEvent sse) {
  final named = sse.event;
  if (named != null && named.isNotEmpty && named != 'message') {
    return named;
  }
  final data = sse.data.trimLeft();
  if (!data.startsWith('{')) {
    return null;
  }
  try {
    final parsed = jsonDecode(data);
    if (parsed is Map<String, dynamic> && parsed['type'] is String) {
      return parsed['type'] as String;
    }
  } on FormatException {
    return null;
  }
  return null;
}
```

Considerations:

1. **Correctness of the fix**: Previously, `sse.event` null (bare `data:` frames) → `_anthropicMessageEvents.contains(null)` → false → skip → empty response. Now the payload `type` is used. Good.

2. **`named != 'message'` — treating the SSE default `message` as "absent"**: Per SSE spec, `event: message` IS the default event name; a proxy could emit it explicitly. Falling back is correct. But subtle: what if a real Anthropic-compatible server sends a genuine event named `message`? Not in Anthropic's protocol. Fine.

3. **Potential issue — `jsonDecode` on huge multi-line data?** Not a real concern.

4. **Double JSON parse**: `_sseEventName` parses with `jsonDecode`, then `_parseSseEvent` parses again with `parseJsonWithRepair` (which likely has repair logic). Minor performance overhead per event — each SSE frame's JSON is parsed twice. Acceptable for correctness/clarity, but worth a suggestion. Actually, this is a fairly common tradeoff; per-frame parse of small JSON objects is cheap relative to network. SUGGESTION at most.

5. **`parsed is Map<String, dynamic>`**: `jsonDecode` returns `Map<String, dynamic>` for JSON objects, so fine. But if `type` is a String that's NOT in `_anthropicMessageEvents` (e.g. 'ping'), returns it, and `_handleSseEvent` skips (not contained). Good — `ping` frames without event lines are skipped, matching the named behavior.

6. **Error event with no event: line**: data `{"type":"error","error":{...}}` → name = 'error' → `throw StateError(sse.data)`. Good, preserved.

7. **What about `data: [DONE]`?** starts with `[` → null → skipped. Good. Note: Anthropic protocol doesn't send [DONE], but OpenAI-compatible proxies bridging might. Fine.

8. **Edge — `named.isNotEmpty`**: decoder can produce empty-string event if `event:` line with empty value (`event: \r\n`). Then falls back to payload type. Good defensive.

9. **Behavior change for frames with a REAL event name whose payload disagrees**: If a server sends `event: content_block_delta` with data type `message_delta`, the handler dispatches by `event['type']` anyway (`_eventHandlers[event['type']]`), so consistent. No change.

10. **The `FormatException` catch**: `jsonDecode` throws `FormatException` on bad JSON. But could it throw anything else? For deeply nested JSON it can throw StackOverflow? No — dart:convert has a depth guard? Actually jsonDecode can throw `FormatException` for recursive depth issues ("json depth limit"?). There isn't a formal limit. Fine.

Hmm wait — actually one subtle bug potential: `sse.data` could contain multiple `data:` lines joined with `\n`. If a frame has `data: {"type":` and `data: "message_start"}` (multi-line JSON split across data lines per spec), then data = `{"type":\n"message_start"}` — jsonDecode handles embedded newline fine since JSON whitespace allows \n. OK.

11. **`trimLeft()`** — only strips leading whitespace. `jsonDecode` tolerates trailing whitespace. Fine.

