/// (e.g. `ping`) are skipped, per pi's `iterateAnthropicEvents`.
const _anthropicMessageEvents = {
  'message_start',
  'message_delta',
  'message_stop',
  'content_block_start',
  'content_block_delta',
  'content_block_stop',
};

